'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { useId, useRef, useState } from 'react';

import {
  BlocksIcon,
  PlusIcon,
  RefreshCwIcon,
  XIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Switch } from '@/registry/ndeko/ui/switch';

import { ActionButton, useTimedAction } from './_parts/action-button';
import { CopyButton } from './_parts/copy-button';
import {
  ModalCloseButton,
  ModalDescription,
  ModalFooter,
  ModalHeader,
  ModalPreview,
  ModalTitle,
} from './_parts/modal-frame';
import { chipVariantsOf } from './_parts/motion';
import { WORKSPACE_NAME } from './_parts/people';
import { RoleSelect, TEAM_ROLES, type TeamRole } from './_parts/role-select';
import { Swap } from './_parts/swap';

const CODES = [
  ['LAT', '7Q4M', '92K'],
  ['LAT', 'P5ZR', 'W8C'],
  ['LAT', 'K2VF', 'Y4D'],
];

const DOMAIN_PATTERN = /^[a-z0-9-]+(\.[a-z0-9-]+)+$/;

const INITIAL_DOMAINS = ['lattice.example', 'northfield.example'];

function domainLineOf(isOn: boolean, count: number) {
  if (!isOn) {
    return 'Only people you invite can join';
  }
  if (count === 0) {
    return 'Add a domain so people can join with their work e-mail';
  }
  if (count === 1) {
    return 'People with an address at this domain join without an invitation';
  }
  return 'People with an address at these domains join without an invitation';
}

function normalizeDomain(value: string) {
  const trimmed = value.trim();
  const lowered = trimmed.toLowerCase();
  return lowered.replace(/^@/, '');
}

function SectionTitle({
  id,
  children,
}: {
  id?: string;
  children: React.ReactNode;
}) {
  return (
    <h3 id={id} className='text-[13px] font-medium'>
      {children}
    </h3>
  );
}

function JoinCode() {
  const [codeIndex, setCodeIndex] = useState(0);
  const action = useTimedAction();
  const code = CODES[codeIndex];
  const codeText = code.join('-');

  function commitNewCode() {
    setCodeIndex((previous) => {
      const next = previous + 1;
      return next % CODES.length;
    });
  }

  function makeNewCode() {
    action.run(commitNewCode);
  }

  return (
    <section className='flex flex-col gap-2'>
      <SectionTitle>Join with a code</SectionTitle>
      <div className='flex flex-wrap items-center gap-2'>
        <Swap swapKey={codeText} kind='label' className='gap-1'>
          {code.map((part) => (
            <span
              key={part}
              className='keycap-3d rounded-md px-2 py-1 font-mono text-[13px] font-medium tabular-nums'
            >
              {part}
            </span>
          ))}
        </Swap>
        <CopyButton
          text={codeText}
          variant='ghost'
          size='icon-sm'
          aria-label='Copy the join code'
          announcement='Join code copied'
          className='text-muted-foreground'
        />
        <ActionButton
          variant='ghost'
          size='sm'
          state={action.state}
          onClick={makeNewCode}
          idleIcon={<RefreshCwIcon />}
          className='text-muted-foreground ml-auto'
          labels={{
            idle: 'New code',
            working: 'Making a code',
            done: 'New code ready',
          }}
        />
      </div>
      <p className='text-muted-foreground text-xs'>
        People type it in the app after they sign up. A new code ends the old
        one
      </p>
    </section>
  );
}

function DomainChip({
  domain,
  onRemove,
}: {
  domain: string;
  onRemove: (domain: string) => void;
}) {
  const shouldReduceMotion = useReducedMotion();
  const variants = chipVariantsOf(shouldReduceMotion);
  const allowsLayout = !shouldReduceMotion;

  function remove() {
    onRemove(domain);
  }

  return (
    <motion.li
      layout={allowsLayout}
      variants={variants}
      initial='hidden'
      animate='shown'
      exit='hidden'
      className='flex'
    >
      <Badge variant='secondary' className='h-7 gap-1 pr-0.5 pl-2 text-[13px]'>
        {`@${domain}`}
        <button
          type='button'
          aria-label={`Remove ${domain}`}
          onClick={remove}
          className='hover:bg-foreground/10 focus-visible:ring-ring/25 flex size-6 cursor-pointer items-center justify-center rounded-[5px] outline-none focus-visible:ring-[3px]'
        >
          <XIcon className='size-3' />
        </button>
      </Badge>
    </motion.li>
  );
}

function DomainSlot({
  takenDomains,
  onAdd,
}: {
  takenDomains: string[];
  onAdd: (domain: string) => void;
}) {
  const [isOpen, setIsOpen] = useState(false);
  const [draft, setDraft] = useState('');
  const [error, setError] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const errorId = useId();
  const hasError = Boolean(error);

  function open() {
    setIsOpen(true);
    window.requestAnimationFrame(() => {
      inputRef.current?.focus();
    });
  }

  function close() {
    setIsOpen(false);
    setDraft('');
    setError(null);
  }

  function changeDraft(event: React.ChangeEvent<HTMLInputElement>) {
    setDraft(event.target.value);
    setError(null);
  }

  function commit() {
    const domain = normalizeDomain(draft);
    if (domain.length === 0) {
      close();
      return;
    }
    if (!DOMAIN_PATTERN.test(domain)) {
      setError(`${domain} is not a domain like company.com`);
      return;
    }
    if (takenDomains.includes(domain)) {
      setError(`${domain} is already on the list`);
      return;
    }
    onAdd(domain);
    setDraft('');
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Enter') {
      event.preventDefault();
      commit();
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      close();
    }
  }

  if (!isOpen) {
    return (
      <li className='flex'>
        <button
          type='button'
          onClick={open}
          className='hairline-border border-foreground/25 text-muted-foreground hover:bg-foreground/[0.03] hover:text-foreground focus-visible:ring-ring/25 flex h-7 cursor-pointer items-center gap-1 rounded-md border-dashed px-2 text-[13px] outline-none focus-visible:ring-[3px]'
        >
          <PlusIcon className='size-3.5' />
          Add domain
        </button>
      </li>
    );
  }

  return (
    <li className='flex flex-col gap-1'>
      <input
        ref={inputRef}
        type='text'
        autoComplete='off'
        spellCheck={false}
        aria-label='Domain to allow'
        aria-invalid={hasError}
        aria-describedby={errorId}
        placeholder='company.com'
        value={draft}
        onChange={changeDraft}
        onKeyDown={handleKeyDown}
        onBlur={commit}
        className={cn(
          'hairline-border border-foreground/25 placeholder:text-muted-foreground/75 focus-visible:ring-ring/25 h-7 w-40 rounded-md border-dashed bg-transparent px-2 text-base outline-none focus-visible:border-solid focus-visible:ring-[3px] md:text-[13px]',
          hasError && 'border-destructive/60'
        )}
      />
      {hasError && (
        <p id={errorId} className='text-destructive-ink text-xs'>
          {error}
        </p>
      )}
    </li>
  );
}

function DomainJoin() {
  const [isOn, setIsOn] = useState(true);
  const [domains, setDomains] = useState<string[]>(INITIAL_DOMAINS);
  const switchId = useId();
  const line = domainLineOf(isOn, domains.length);

  function addDomain(domain: string) {
    setDomains((previous) => [...previous, domain]);
  }

  function removeDomain(domain: string) {
    setDomains((previous) => previous.filter((item) => item !== domain));
  }

  return (
    <section className='flex flex-col gap-2'>
      <div className='flex items-start justify-between gap-4'>
        <div className='flex min-w-0 flex-col gap-0.5'>
          <label htmlFor={switchId} className='text-[13px] font-medium'>
            Join with a work e-mail
          </label>
          <Swap
            swapKey={line}
            kind='label'
            className='text-muted-foreground flex min-w-0 text-xs'
            contentClassName='max-w-full min-w-0 whitespace-normal'
          >
            {line}
          </Swap>
        </div>
        <Switch id={switchId} checked={isOn} onCheckedChange={setIsOn} />
      </div>
      <AnimatedSize>
        {isOn && (
          <ul
            aria-label='Allowed domains'
            className='relative flex flex-wrap items-start gap-1.5 pt-1'
          >
            <AnimatePresence initial={false} mode='popLayout'>
              {domains.map((domain) => (
                <DomainChip
                  key={domain}
                  domain={domain}
                  onRemove={removeDomain}
                />
              ))}
            </AnimatePresence>
            <DomainSlot takenDomains={domains} onAdd={addDomain} />
          </ul>
        )}
      </AnimatedSize>
    </section>
  );
}

function WorkspaceAccess() {
  const [role, setRole] = useState<TeamRole>('member');
  const roleLabelId = useId();

  return (
    <>
      <div className='flex items-start gap-3 pr-8'>
        <span className='gem-plate flex size-9 shrink-0 items-center justify-center rounded-lg [--gem:var(--primary)]'>
          <BlocksIcon className='size-4' strokeWidth={2.25} />
        </span>
        <ModalHeader className='pr-0'>
          <ModalTitle>Workspace access</ModalTitle>
          <ModalDescription>
            {`Choose how people join ${WORKSPACE_NAME} without an invitation`}
          </ModalDescription>
        </ModalHeader>
      </div>
      <div className='flex flex-col gap-6 pt-1'>
        <JoinCode />
        <DomainJoin />
        <section className='flex items-center justify-between gap-4'>
          <div className='flex min-w-0 flex-col gap-0.5'>
            <SectionTitle id={roleLabelId}>
              Role of people who join
            </SectionTitle>
            <p className='text-muted-foreground text-xs'>
              You can change it for each person later
            </p>
          </div>
          <RoleSelect
            label='Role of people who join'
            value={role}
            options={TEAM_ROLES}
            onValueChange={setRole}
            className='text-foreground'
          />
        </section>
      </div>
      <ModalFooter>
        <ModalCloseButton>Done</ModalCloseButton>
      </ModalFooter>
    </>
  );
}

export default function Modal07() {
  return (
    <ModalPreview triggerLabel='Open the workspace access dialog' size='md'>
      <WorkspaceAccess />
    </ModalPreview>
  );
}

'use client';

import { useEffect, useRef, useState } from 'react';

import { CheckIcon, LoaderCircleIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';

import { Swap } from './swap';

export type ActionState = 'idle' | 'working' | 'done';

export type ActionLabels = Record<ActionState, string>;

const WORKING_MS = 800;

const DONE_MS = 1600;

/** The life of an action that takes a moment: working, then done for a beat, then ready again. The change is committed when the work ends. */
export function useTimedAction() {
  const [state, setState] = useState<ActionState>('idle');
  const commitRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    if (state === 'working') {
      const timeout = window.setTimeout(() => {
        const commit = commitRef.current;
        commitRef.current = null;
        if (commit) {
          commit();
        }
        setState('done');
      }, WORKING_MS);
      return () => window.clearTimeout(timeout);
    }
    if (state === 'done') {
      const timeout = window.setTimeout(() => {
        setState('idle');
      }, DONE_MS);
      return () => window.clearTimeout(timeout);
    }
  }, [state]);

  function run(commit: () => void) {
    if (state !== 'idle') {
      return;
    }
    commitRef.current = commit;
    setState('working');
  }

  const isBusy = state !== 'idle';

  return { state, run, isBusy };
}

function iconOf(state: ActionState, idleIcon: React.ReactNode) {
  if (state === 'working') {
    return <LoaderCircleIcon className='animate-spin' />;
  }
  if (state === 'done') {
    return <CheckIcon />;
  }
  return idleIcon;
}

type ActionButtonProps = Omit<ButtonProps, 'children'> & {
  state: ActionState;
  labels: ActionLabels;
  idleIcon?: React.ReactNode;
};

/** One button that becomes its next state: its icon swaps, its label crossfades and its width follows the new label. */
export function ActionButton({
  state,
  labels,
  idleIcon,
  ...props
}: ActionButtonProps) {
  const icon = iconOf(state, idleIcon);
  const hasIcon = Boolean(icon);
  const label = labels[state];
  const isWorking = state === 'working';
  const isDone = state === 'done';

  return (
    <>
      <Button aria-busy={isWorking} {...props}>
        {hasIcon && <Swap swapKey={state}>{icon}</Swap>}
        <AnimatedSize axis='width' as='span'>
          <Swap swapKey={label} kind='label'>
            {label}
          </Swap>
        </AnimatedSize>
      </Button>
      <span className='sr-only' role='status'>
        {isDone && labels.done}
      </span>
    </>
  );
}

'use client';

import { useEffect, useState } from 'react';

import { CheckIcon, CopyIcon, LinkIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';

import { Swap } from './swap';

const COPIED_RESET_MS = 1600;

/** Copies a text and says so for a moment. */
export function useCopy(text: string) {
  const [isCopied, setIsCopied] = useState(false);

  useEffect(() => {
    if (!isCopied) {
      return;
    }
    const timeout = window.setTimeout(() => {
      setIsCopied(false);
    }, COPIED_RESET_MS);
    return () => window.clearTimeout(timeout);
  }, [isCopied]);

  async function copy() {
    try {
      await navigator.clipboard.writeText(text);
      setIsCopied(true);
    } catch {
      setIsCopied(false);
    }
  }

  return { isCopied, copy };
}

type CopyGlyph = 'copy' | 'link';

function glyphOf(isCopied: boolean, glyph: CopyGlyph) {
  if (isCopied) {
    return <CheckIcon className='text-success-foreground' />;
  }
  if (glyph === 'link') {
    return <LinkIcon />;
  }
  return <CopyIcon />;
}

function labelOf(isCopied: boolean, label: string, copiedLabel: string) {
  if (isCopied) {
    return copiedLabel;
  }
  return label;
}

type CopyButtonProps = Omit<ButtonProps, 'children' | 'onClick'> & {
  text: string;
  /** Visible label. Leave it out for an icon button, and give `aria-label` instead. */
  label?: string;
  copiedLabel?: string;
  /** Announced once the text is on the clipboard. */
  announcement: string;
  glyph?: CopyGlyph;
};

/** A copy action whose icon becomes a check and whose label becomes Copied, then returns. */
export function CopyButton({
  text,
  label,
  copiedLabel = 'Copied',
  announcement,
  glyph = 'copy',
  variant = 'outline',
  size = 'sm',
  ...props
}: CopyButtonProps) {
  const { isCopied, copy } = useCopy(text);
  const icon = glyphOf(isCopied, glyph);
  const iconKey = String(isCopied);
  const hasLabel = Boolean(label);
  const shownLabel = labelOf(isCopied, label ?? '', copiedLabel);

  return (
    <>
      <Button variant={variant} size={size} onClick={copy} {...props}>
        <Swap swapKey={iconKey}>{icon}</Swap>
        {hasLabel && (
          <AnimatedSize axis='width' as='span'>
            <Swap swapKey={shownLabel} kind='label'>
              {shownLabel}
            </Swap>
          </AnimatedSize>
        )}
      </Button>
      <span className='sr-only' role='status'>
        {isCopied && announcement}
      </span>
    </>
  );
}

'use client';

import { createContext, useContext } from 'react';

import { SquareArrowOutUpRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogTitle,
  DialogTrigger,
} from '@/registry/ndeko/ui/dialog';

/** Where a modal's content is drawn: open in the page as a preview, or inside the real dialog. */
export type ModalHost = 'preview' | 'dialog';

const ModalHostContext = createContext<ModalHost>('preview');

export function useModalHost() {
  return useContext(ModalHostContext);
}

export type ModalSize = 'sm' | 'md' | 'lg' | 'xl';

const SIZE_CLASS: Record<ModalSize, string> = {
  sm: 'max-w-sm',
  md: 'max-w-md',
  lg: 'max-w-lg',
  xl: 'max-w-[44rem]',
};

const TITLE = 'text-lg leading-tight font-semibold text-balance';

const DESCRIPTION = 'text-muted-foreground text-[13px]';

const BODY = 'flex flex-col gap-4';

type ModalTextProps = { className?: string; children: React.ReactNode };

export function ModalTitle({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogTitle className={className}>{children}</DialogTitle>;
  }
  return <h2 className={cn(TITLE, className)}>{children}</h2>;
}

export function ModalDescription({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return (
      <DialogDescription className={className}>{children}</DialogDescription>
    );
  }
  return <p className={cn(DESCRIPTION, className)}>{children}</p>;
}

/** Leaves room for the dialog's close button, so the preview and the dialog lay out the same. */
export function ModalHeader({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div className={cn('flex flex-col gap-1.5 pr-8', className)} {...props} />
  );
}

export function ModalFooter({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div
      className={cn(
        'flex flex-col-reverse gap-2 sm:flex-row sm:items-center sm:justify-end',
        className
      )}
      {...props}
    />
  );
}

/** Closes the dialog. In the preview it stays a plain button that runs its own action, if any. */
export function ModalCloseButton({ children, ...props }: ButtonProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogClose render={<Button {...props} />}>{children}</DialogClose>;
  }
  return <Button {...props}>{children}</Button>;
}

type ModalPreviewProps = {
  /** The content, drawn twice: open in the page, and inside the dialog the trigger opens. */
  children: React.ReactNode;
  triggerLabel: string;
  size?: ModalSize;
  className?: string;
};

/** Shows a modal open and whole on the page, with a small trigger that opens the same content in the real dialog. */
export function ModalPreview({
  children,
  triggerLabel,
  size = 'md',
  className,
}: ModalPreviewProps) {
  const sizeClass = SIZE_CLASS[size];

  return (
    <div className='flex w-full flex-col items-center gap-4'>
      <ModalHostContext.Provider value='preview'>
        <div
          className={cn(
            'surface-raised w-full rounded-2xl p-6 text-left',
            sizeClass,
            className
          )}
        >
          <AnimatedSize contentClassName={BODY}>{children}</AnimatedSize>
        </div>
      </ModalHostContext.Provider>
      <Dialog>
        <DialogTrigger render={<Button variant='outline' size='sm' />}>
          <SquareArrowOutUpRightIcon />
          {triggerLabel}
        </DialogTrigger>
        <DialogContent className={cn(sizeClass, className)}>
          <ModalHostContext.Provider value='dialog'>
            {children}
          </ModalHostContext.Provider>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import type { Transition, Variants } from 'motion/react';

export const SWAP_TRANSITION: Transition = {
  duration: 0.15,
  ease: [0.2, 0, 0, 1],
};

const MORPH_SPRING: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INSTANT: Transition = { duration: 0 };

const PRESENCE_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const PRESENCE_OUT: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const ICON_SWAP: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const LABEL_SWAP: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, filter: 'blur(2px)' },
};

const FADE_SWAP: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const ROW_PRESENCE: Variants = {
  hidden: {
    height: 0,
    opacity: 0,
    overflow: 'hidden',
    transition: PRESENCE_OUT,
  },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: PRESENCE_IN,
    transitionEnd: { overflow: 'visible' },
  },
};

const ROW_FADE: Variants = {
  hidden: { opacity: 0, transition: PRESENCE_OUT },
  shown: { opacity: 1, transition: PRESENCE_IN },
};

const CHIP_PRESENCE: Variants = {
  hidden: { opacity: 0, scale: 0.9, transition: PRESENCE_OUT },
  shown: { opacity: 1, scale: 1, transition: PRESENCE_IN },
};

export type SwapKind = 'icon' | 'label';

export function swapVariantsOf(
  shouldReduceMotion: boolean | null,
  kind: SwapKind = 'icon'
) {
  if (shouldReduceMotion) {
    return FADE_SWAP;
  }
  if (kind === 'label') {
    return LABEL_SWAP;
  }
  return ICON_SWAP;
}

/** A row added to or removed from a list: its height opens or collapses, so the rows after it slide. */
export function rowVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return ROW_PRESENCE;
}

export function chipVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return CHIP_PRESENCE;
}

export function morphOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MORPH_SPRING;
}

