type RoleSelectProps<Value extends string> = {
  value: Value;
  options: RoleOption<Value>[];
  onValueChange: (value: Value) => void;
  /** Names the select for screen readers, since its trigger shows the value only. */
  label: string;
  disabled?: boolean;
  className?: string;
};

/** A compact role picker that fits in a field or at the end of a row; its menu says what each role can do. */
export function RoleSelect<Value extends string>({
  value,
  options,
  onValueChange,
  label,
  disabled,
  className,
}: RoleSelectProps<Value>) {
  function changeValue(nextValue: unknown) {
    const option = options.find((candidate) => candidate.value === nextValue);
    if (option) {
      onValueChange(option.value);
    }
  }

  return (
    <Select
      items={options}
      value={value}
      disabled={disabled}
      onValueChange={changeValue}
    >
      <SelectTrigger
        size='sm'
        aria-label={label}
        className={cn(
          'text-muted-foreground hover:bg-foreground/5 hover:text-foreground data-popup-open:bg-foreground/5 w-auto min-w-0 shrink-0 gap-1 border-transparent bg-transparent px-2 shadow-none ring-0 dark:bg-transparent',
          className
        )}
      >
        <SelectValue />
      </SelectTrigger>
      <SelectContent align='end' className='w-72'>
        {options.map((option) => {
          const RoleGlyph = option.icon;
          const tileStyle = { '--chip': option.color } as React.CSSProperties;

          return (
            <SelectItem
              key={option.value}
              value={option.value}
              className='h-auto py-1.5'
            >
              <span
                style={tileStyle}
                className='chip-3d flex size-7 shrink-0 items-center justify-center rounded-md'
              >
                <RoleGlyph className='size-3.5 text-current' />
              </span>
              <span className='flex min-w-0 flex-col'>
                <span className='text-foreground text-[13px] font-medium'>
                  {option.label}
                </span>
                <span className='text-muted-foreground truncate text-xs leading-snug'>
                  {option.line}
                </span>
              </span>
            </SelectItem>
          );
        })}
      </SelectContent>
    </Select>
  );
}

'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';

import { cn } from '@/registry/ndeko/lib/utils';

import { SWAP_TRANSITION, swapVariantsOf, type SwapKind } from './motion';

type SwapProps = {
  /** Changes when the content becomes another: the old one leaves while the new one arrives in its place. */
  swapKey: string;
  kind?: SwapKind;
  className?: string;
  /** Classes of the moving content, for example `min-w-0 max-w-full` so a long text can truncate inside. */
  contentClassName?: string;
  children: React.ReactNode;
};

export function Swap({
  swapKey,
  kind = 'icon',
  className,
  contentClassName,
  children,
}: SwapProps) {
  const shouldReduceMotion = useReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion, kind);

  return (
    <span className={cn('relative inline-flex items-center', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          className={cn(
            'inline-flex items-center gap-[inherit] whitespace-nowrap',
            contentClassName
          )}
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}
